$('lesson-mode').addEventListener('change',renderLessonChoices);
$('lesson-create').addEventListener('submit',guarded(async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const scenarios=[...document.querySelectorAll('#lesson-scenarios input:checked')].map(input=>Number(input.value));const students=[...document.querySelectorAll('#lesson-students input:checked')].map(input=>Number(input.value));await api('/api/lessons',{method:'POST',body:JSON.stringify({title:$('lesson-title').value,mode:$('lesson-mode').value,service_code:$('lesson-service').value.trim(),scenario_ids:scenarios,student_ids:students})});event.target.reset();await loadLessons();}finally{button.disabled=false;}}));
function renderLessonList(){$('lesson-list').replaceChildren();if(!state.lessons.length)$('lesson-list').append(el('div','panel empty-table','Занятия пока не назначены.'));for(const lesson of state.lessons){const panel=el('article','panel lesson-panel');panel.append(el('h2','',lesson.title),el('p','',`${lesson.mode==='dispatch'?'Действия с карточками ДДС':'Заполнение карточек'} · ${({prepared:'Подготовлено',active:'Идёт занятие',finished:'Завершено'})[lesson.status]} · ${lesson.scenario_ids.length} заданий`));const actions=el('div','result-actions');if(state.role==='teacher'){if(lesson.status!=='finished'){const control=el('button','primary',lesson.status==='prepared'?'Начать занятие →':'Завершить занятие');control.addEventListener('click',guarded(async()=>{control.disabled=true;try{await api(`/api/lessons/${lesson.id}/${lesson.status==='prepared'?'start':'stop'}`,{method:'POST'});await loadData();renderLessonList();}finally{control.disabled=false;}}));actions.append(control);}const monitor=el('button','secondary','Мониторинг и отчёт');monitor.addEventListener('click',guarded(()=>monitorLesson(lesson.id)));actions.append(monitor);}if(state.role==='student'&&lesson.status==='active'){const next=el('button','primary','Получить карточку →');next.addEventListener('click',guarded(()=>nextLesson(lesson.id)));actions.append(next);}panel.append(actions);$('lesson-list').append(panel);}}
async function monitorLesson(identifier){state.monitoredLesson=identifier;const runs=await api(`/api/lessons/${identifier}/monitor`);const panel=$('lesson-monitor');show('lesson-monitor',true);panel.replaceChildren(el('h2','','Действия обучающихся · обновление каждые 5 секунд'));if(!runs.length)panel.append(el('p','muted','Обучающиеся ещё не приступили к заданиям.'));for(const run of runs){const node=el('div','monitor-card');node.append(el('b','',`${run.student_name} · карточка ${run.run_id}`),el('p','',`${run.finished_at?'Завершена':'В работе'} · ${run.status} · ${run.card.address||'Адрес ещё не указан'}`),el('p','',run.card.description||'Описание ещё не введено'));for(const event of run.events.slice(-5))node.append(el('p','source-meta',`${date(event.at)} · ${event.kind==='service.status'?event.data.status:({'card.draft':'Сохранён черновик','card.finish':'Тренировка завершена','card.skip':'Карточка пропущена студентом','card.resume':'Работа с карточкой возобновлена','work.call':'Добавлена строка отработки','card.checked':'Карточка проверена'})[event.kind]||'Действие с карточкой'}`));const preview=el('button','secondary','Открыть карточку');preview.addEventListener('click',()=>{const detail=el('div','panel');renderSavedCard(detail,run);node.append(detail);preview.disabled=true;});node.append(preview);if(run.registered_at){const checked=el('button','secondary','Карточка проверена ✓');checked.addEventListener('click',guarded(async()=>{await api(`/api/runs/${run.run_id}/checked`,{method:'POST'});await monitorLesson(identifier);}));node.append(checked);}if(run.report){renderResult(node.appendChild(el('div','result')),run.report);const report=state.reports.find(report=>report.id===run.run_id);if(report)renderExpertReview(node,report);}panel.append(node);}}
function renderExpertReview(container,run){const box=el('div','expert-box');box.append(el('h2','','Экспертная оценка преподавателя'));if(run.expert_review){box.append(el('p','',`${run.expert_review.score} / 100 · ${run.expert_review.comment}`),el('small','source-meta',date(run.expert_review.at)));}else box.append(el('p','muted','Преподаватель ещё не добавил экспертную оценку.'));if(state.role==='teacher'){const form=el('form');const score=el('input');score.type='number';score.min=0;score.max=100;score.required=true;score.placeholder='Оценка 0–100';score.value=run.expert_review?.score??run.score;const comment=el('textarea');comment.required=true;comment.placeholder='Замечания и рекомендации обучающемуся';form.append(score,comment,el('button','primary','Сохранить оценку и комментарий'));form.addEventListener('submit',guarded(async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await api(`/api/runs/${run.id}/review`,{method:'POST',body:JSON.stringify({score:Number(score.value),comment:comment.value})});await refreshReports();const updated=state.reports.find(report=>report.id===run.id);box.remove();renderExpertReview(container,updated);}finally{button.disabled=false;}}));box.append(form);}container.append(box);}
setInterval(async()=>{if(!state.token||state.busy)return;try{if(!$('cards-view').hidden&&$('cards-autorefresh').checked)await loadFeed();if(!$('lessons-view').hidden&&state.role==='teacher'&&state.monitoredLesson&&!$('lesson-monitor').contains(document.activeElement))await monitorLesson(state.monitoredLesson);if(state.role==='student'){const lessons=await api('/api/lessons');if(JSON.stringify(lessons)!==JSON.stringify(state.lessons)){state.lessons=lessons;await loadData();renderLessonList();}if(state.runId){const run=await api(`/api/runs/${state.runId}`);if(run.finished_at){clearInterval(state.timer);clearDraftCache();state.runId=null;state.registered=false;show('incident-form',false);show('saved-card',false);show('result',true);renderResult($('result'),run.report,true);notify(run.report?.skipped?'Карточка пропущена без оценки. Выберите другой сценарий.':'Преподаватель завершил занятие. Сохранён результат текущей карточки.');await loadData();}}}}catch{/* Retry polling when the local network returns. */}},5000);

async function loadUsers(){const users=await api('/api/users');table($('user-list'),['Логин','Роль','Доступ','Действия'],users.map(user=>{const role=el('select');for(const [key,name] of Object.entries(roleNames)){const option=el('option','',name);option.value=key;role.append(option);}role.value=user.role;role.style.margin='0';const blocked=el('input');blocked.type='checkbox';blocked.checked=user.blocked;const label=el('label');label.append(blocked,el('span','',' Заблокирован'));const button=el('button','table-button','Сохранить');button.addEventListener('click',guarded(async()=>{button.disabled=true;try{await api(`/api/users/${user.id}`,{method:'PUT',body:JSON.stringify({role:role.value,blocked:blocked.checked})});await loadUsers();}finally{button.disabled=false;}}));const remove=el('button','table-button','Удалить');remove.addEventListener('click',guarded(async()=>{if(!confirm(`Удалить пользователя ${user.username} вместе с его карточками и аудио?`))return;remove.disabled=true;await api(`/api/users/${user.id}`,{method:'DELETE'});await loadUsers();}));const actions=el('div','result-actions');actions.append(button,remove);return [user.username,role,label,actions];}));}
$('user-create').addEventListener('submit',guarded(async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{await api('/api/users',{method:'POST',body:JSON.stringify({username:$('account-name').value,password:$('account-password').value,role:$('account-role').value})});event.target.reset();await loadUsers();}finally{button.disabled=false;}}));

$('export-reports').addEventListener('click',guarded(async()=>{const response=await fetch('/api/reports/export.csv',{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw Error('Не удалось выгрузить отчёт');const url=URL.createObjectURL(await response.blob());const link=el('a');link.href=url;link.download='arm112-results.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}));

$('skip-card').addEventListener('click',guarded(async()=>{
 if(!state.runId||state.busy)return;
 state.busy=true;$('skip-card').disabled=true;
 try{
  clearTimeout(state.draftTimeout);
  if(state.savePromise)await state.savePromise;
  if(!state.registered&&state.mode!=='dispatch')await saveDraft();
  await api(`/api/runs/${state.runId}/skip`,{method:'POST'});
  if(typeof stopTrainingPhone==='function')stopTrainingPhone();
  clearInterval(state.timer);clearDraftCache();
  state.runId=null;state.registered=false;state.selected=null;state.pendingDraft=null;
  for(const id of ['incident-form','saved-card','call','result'])show(id,false);
  show('empty-state',true);$('incident-title').textContent='Новая тренировка';$('run-badge').textContent='Карточка пропущена';
  resetClassifier();document.querySelector('.scenario-panel').classList.remove('collapsed');renderMetrics();renderScenarios();await loadData();
  notify('Карточка пропущена без оценки. Выберите другой сценарий.');
 }finally{state.busy=false;$('skip-card').disabled=false;}
}));
